IF DB_ID(N'BilliardsDB') IS NULL CREATE DATABASE BilliardsDB;
GO
USE BilliardsDB;
GO
IF OBJECT_ID(N'dbo.BanBida',N'U') IS NULL CREATE TABLE dbo.BanBida(MaBan INT IDENTITY PRIMARY KEY,TenBan NVARCHAR(50) NOT NULL,LoaiBan NVARCHAR(30) NOT NULL,GiaTheoGio DECIMAL(18,2) NOT NULL CHECK(GiaTheoGio>=0),TrangThai NVARCHAR(20) NOT NULL DEFAULT N'Trống');
IF OBJECT_ID(N'dbo.MenuDichVu',N'U') IS NULL CREATE TABLE dbo.MenuDichVu(MaDV INT IDENTITY PRIMARY KEY,TenDV NVARCHAR(100) NOT NULL,DonGia DECIMAL(18,2) NOT NULL CHECK(DonGia>=0),TonKho INT NOT NULL CHECK(TonKho>=0),LaDichVuThue BIT NOT NULL DEFAULT 0);
IF OBJECT_ID(N'dbo.HoaDon',N'U') IS NULL CREATE TABLE dbo.HoaDon(MaHD INT IDENTITY PRIMARY KEY,MaBan INT NOT NULL REFERENCES dbo.BanBida(MaBan),GioBatDau DATETIME NOT NULL,GioKetThuc DATETIME NULL,TienGioChoi DECIMAL(18,2) NOT NULL DEFAULT 0,TienDichVu DECIMAL(18,2) NOT NULL DEFAULT 0,TrangThai BIT NOT NULL DEFAULT 0);
IF OBJECT_ID(N'dbo.ChiTietHoaDon',N'U') IS NULL CREATE TABLE dbo.ChiTietHoaDon(MaHD INT NOT NULL REFERENCES dbo.HoaDon(MaHD),MaDV INT NOT NULL REFERENCES dbo.MenuDichVu(MaDV),SoLuong INT NOT NULL CHECK(SoLuong>0),DonGia DECIMAL(18,2) NOT NULL,CONSTRAINT PK_ChiTietHoaDon PRIMARY KEY(MaHD,MaDV));
IF NOT EXISTS(SELECT 1 FROM dbo.BanBida) INSERT dbo.BanBida(TenBan,LoaiBan,GiaTheoGio,TrangThai) VALUES(N'Bàn Lỗ 01',N'Pool (Lỗ)',80000,N'Trống'),(N'Bàn Lỗ 02',N'Pool (Lỗ)',80000,N'Trống'),(N'Bàn Carom 01',N'Carom (Phăng)',70000,N'Trống'),(N'Bàn Carom 02',N'Carom (Phăng)',70000,N'Trống'),(N'Bàn Snooker 01',N'Snooker',120000,N'Trống'),(N'Bàn Snooker 02',N'Snooker',120000,N'Trống');
IF NOT EXISTS(SELECT 1 FROM dbo.MenuDichVu) INSERT dbo.MenuDichVu(TenDV,DonGia,TonKho,LaDichVuThue) VALUES(N'Nước tăng lực Sting',18000,50,0),(N'Nước suối',10000,60,0),(N'Mì xào bò',45000,25,0),(N'Thuê gậy Carbon',30000,0,1),(N'Khăn lạnh',5000,80,0);
GO
